5|
6|import ConfigCarrier from "@components/ConfigCarrier.astro";
7|import { profileConfig, siteConfig } from "@/config";
8|import {
9|	AUTO_MODE,
10|	BANNER_HEIGHT,
11|	BANNER_HEIGHT_EXTEND,
12|	BANNER_HEIGHT_HOME,
13|	DARK_MODE,
14|	DEFAULT_THEME,
15|	LIGHT_MODE,
16|	PAGE_WIDTH,
17|} from "../constants/constants";
18|import { defaultFavicons } from "../constants/icon";
19|import type { Favicon } from "../types/config";
20|import { pathsEqual, url } from "../utils/url-utils";
21|import "katex/dist/katex.css";
22|
23|interface Props {
24|	title?: string;
25|	banner?: string;
26|	description?: string;
27|	lang?: string;
28|	setOGTypeArticle?: boolean;
29|}
30|
31|let { title, banner, description, lang, setOGTypeArticle } = Astro.props;
32|
33|// apply a class to the body element to decide the height of the banner, only used for initial page load
34|// Swup can update the body for each page visit, but it's after the page transition, causing a delay for banner height change
35|// so use Swup hooks instead to change the height immediately when a link is clicked
36|const isHomePage = pathsEqual(Astro.url.pathname, url("/"));
37|
38|// defines global css variables
39|// why doing this in Layout instead of GlobalStyles: https://github.com/withastro/astro/issues/6728#issuecomment-1502203757
40|const configHue = siteConfig.themeColor.hue;
41|if (!banner || typeof banner !== "string" || banner.trim() === "") {
42|	banner = siteConfig.banner.src;
43|}
44|
45|// TODO don't use post cover as banner for now
46|banner = siteConfig.banner.src;
47|
48|const enableBanner = siteConfig.banner.enable;
49|
50|let pageTitle: string;
51|if (title) {
52|	pageTitle = `${title} - ${siteConfig.title}`;
53|} else {
54|	pageTitle = `${siteConfig.title} - ${siteConfig.subtitle}`;
55|}
56|
57|const favicons: Favicon[] =
58|	siteConfig.favicon.length > 0 ? siteConfig.favicon : defaultFavicons;
59|
60|// const siteLang = siteConfig.lang.replace('_', '-')
61|if (!lang) {
62|	lang = `${siteConfig.lang}`;
63|}
64|const siteLang = lang.replace("_", "-");
65|
66|const bannerOffsetByPosition = {
67|	top: `${BANNER_HEIGHT_EXTEND}vh`,
68|	center: `${BANNER_HEIGHT_EXTEND / 2}vh`,
69|	bottom: "0",
70|};
71|const bannerOffset =
72|	bannerOffsetByPosition[siteConfig.banner.position || "center"];
