75|<!DOCTYPE html>
76|<html lang={siteLang} class="bg-[var(--page-bg)] transition text-[14px] md:text-[16px]"
77|	  data-overlayscrollbars-initialize
78|>
79|	<head>
80|        <!--  meta不用管 -->
81|		<title>{pageTitle}</title>
82|
83|		<meta charset="UTF-8" />
84|		<meta name="description" content={description || pageTitle}>
85|		<meta name="author" content={profileConfig.name}>
86|
87|		<meta property="og:site_name" content={siteConfig.title}>
88|		<meta property="og:url" content={Astro.url}>
