101|
102|		<meta name="viewport" content="width=device-width" />
103|		<meta name="generator" content={Astro.generator} />
104|		{favicons.map(favicon => (
105|			<link rel="icon"
106|				  href={favicon.src.startsWith('/') ? url(favicon.src) : favicon.src}
107|				  sizes={favicon.sizes}
108|				  media={favicon.theme && `(prefers-color-scheme: ${favicon.theme})`}
109|			/>
110|		))}
111|
112|		<!-- Set the theme before the page is rendered to avoid a flash防闪烁脚本 -->
113|		<script is:inline define:vars={{DEFAULT_THEME, LIGHT_MODE, DARK_MODE, AUTO_MODE, BANNER_HEIGHT_EXTEND, PAGE_WIDTH, configHue}}>
114|			// Load the theme from local storage
115|			const theme = localStorage.getItem('theme') || DEFAULT_THEME;
116|			switch (theme) {
117|				case LIGHT_MODE:
118|					document.documentElement.classList.remove('dark');
119|					break
120|				case DARK_MODE:
121|					document.documentElement.classList.add('dark');
122|					break
123|				case AUTO_MODE:
124|					if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
125|						document.documentElement.classList.add('dark');
126|					} else {
127|						document.documentElement.classList.remove('dark');
128|					}
129|			}
130|
131|			// Load the hue from local storage
132|			const hue = localStorage.getItem('hue') || configHue;
133|			document.documentElement.style.setProperty('--hue', hue);
134|
135|			// calculate the --banner-height-extend, which needs to be a multiple of 4 to avoid blurry text
136|			let offset = Math.floor(window.innerHeight * (BANNER_HEIGHT_EXTEND / 100));
137|			offset = offset - offset % 4;
138|			document.documentElement.style.setProperty('--banner-height-extend', `${offset}px`);
139|		</script>
140|		<style define:vars={{
141|			configHue,
142|			'page-width': `${PAGE_WIDTH}rem`,
143|		}}></style>  <!-- defines global css variables. This will be applied to <html> <body> and some other elements idk why -->
144|
145|
146|		<slot name="head"></slot>
147|
148|		<link rel="alternate" type="application/rss+xml" title={profileConfig.name} href={`${Astro.site}rss.xml`}/>
149|
150|	</head>
151|	<body class=" min-h-screen transition " class:list={[{"lg:is-home": isHomePage, "enable-banner": enableBanner}]}
152|		  data-overlayscrollbars-initialize
153|	>
154|		<ConfigCarrier></ConfigCarrier>
155|		<slot />
156|
157|		<!-- increase the page height during page transition to prevent the scrolling animation from jumping -->
158|		<div id="page-height-extend" class="hidden h-[300vh]"></div>
159|	</body>
160|</html>
161|
162|<style is:global define:vars={{
163|	bannerOffset,
164|	'banner-height-home': `${BANNER_HEIGHT_HOME}vh`,
165|	'banner-height': `${BANNER_HEIGHT}vh`,
166|}}>
167|@tailwind components;
168|@layer components {
169|	.enable-banner.is-home #banner-wrapper {
170|		@apply h-[var(--banner-height-home)] translate-y-[var(--banner-height-extend)]
171|	}
172|	.enable-banner #banner-wrapper {
173|		@apply h-[var(--banner-height-home)]
174|	}
175|
176|	.enable-banner.is-home #banner {
