178|	}
179|	.enable-banner #banner {
180|		@apply h-[var(--banner-height-home)] translate-y-[var(--bannerOffset)]
181|	}
182|	.enable-banner.is-home #main-grid {
183|		@apply translate-y-[var(--banner-height-extend)];
184|	}
185|	.enable-banner #top-row {
186|		@apply h-[calc(var(--banner-height-home)_-_4.5rem)] transition-all duration-300
187|	}
188|	/*.enable-banner.is-home #sidebar-sticky {
189|		@apply top-[calc(1rem_-_var(--banner-height-extend))]
190|	}*/   /*判断是否为主页面，是主页面就下滑一些留出空间给banner（banner已删除，故弃用）*/ 
191|	.navbar-hidden {
192|		@apply opacity-0 -translate-y-16
193|	}
194|	/* Layout.astro 全局样式里增加覆盖（放在现有 banner 规则后面） */
195|
196|	.enable-banner #banner-wrapper {
197|	position: fixed !important;
198|	inset: 0 !important;
199|	top: 0 !important;
200|	height: 100vh !important;
201|	transform: none !important;
202|	}
