477|function updateBannerByScrollProgress() {
478|	const wrapper = document.getElementById('banner-wrapper');
479|	const banner = document.getElementById('banner') as HTMLElement | null;
480|	if (!wrapper || !banner) return;
481|
482|	const scrollTop = window.scrollY || document.documentElement.scrollTop || 0;
483|	const pageHeight = document.documentElement.scrollHeight;
484|	const viewport = window.innerHeight;
485|	const maxScroll = Math.max(1, pageHeight - viewport);
486|	const progress = Math.min(1, Math.max(0, scrollTop / maxScroll));
487|
488|	const imageHeight = banner.offsetHeight;
489|	const maxShift = Math.max(0, imageHeight - viewport);
490|	const shift = maxShift * progress;
491|
492|	banner.style.transform = `translateY(${-shift}px)`;
493|}
