521|		const MAIN_PANEL_EXCESS_HEIGHT = MAIN_PANEL_OVERLAPS_BANNER_HEIGHT * 16			// The height the main panel overlaps the banner
522|
523|		let bannerHeight = BANNER_HEIGHT
524|		if (document.body.classList.contains('lg:is-home') && window.innerWidth >= 1024) {
525|			bannerHeight = BANNER_HEIGHT_HOME
526|		}
527|		let threshold = window.innerHeight * (bannerHeight / 100) - NAVBAR_HEIGHT - MAIN_PANEL_EXCESS_HEIGHT - 16
