2|import MainGridLayout from "@layouts/MainGridLayout.astro";
3|---
4|
5|<MainGridLayout title="评论">
6|  <div class="card-base rounded-2xl p-5 md:p-6 mb-4">
7|    <h1 class="text-3xl font-bold mb-4">评论</h1>
8|    <div id="comments-list" class="flex flex-col gap-4">加载中...</div>
9|  </div>
10|
11|  <script is:inline>
12|    function escapeHtml(str) {
13|      return String(str)
14|        .replaceAll("&", "&amp;")
15|        .replaceAll("<", "&lt;")
16|        .replaceAll(">", "&gt;")
17|        .replaceAll('"', "&quot;")
18|        .replaceAll("'", "&#39;");
19|    }
20|
21|    function renderComments(list) {
22|      const listEl = document.getElementById("comments-list");
23|      if (!listEl) return;
24|
25|      if (!Array.isArray(list) || list.length === 0) {
26|        listEl.innerHTML = '<div class="text-75">暂无评论</div>';
27|        return;
28|      }
29|
30|      listEl.innerHTML = list
31|        .map((item) => {
32|          const author = escapeHtml(item?.author ?? "匿名");
33|          const comment = escapeHtml(item?.comment ?? "");
34|          return `
35|            <article class="rounded-xl border border-black/10 dark:border-white/10 bg-[var(--btn-regular-bg)] p-4">
36|              <div class="text-xs opacity-60 mb-1">文章ID：${escapeHtml(item?.post_id ?? "")}</div>
37|              <div class="font-semibold text-black/90 dark:text-white/90 mb-2">${author}</div>
38|              <p class="text-75 leading-7 whitespace-pre-wrap break-words">${comment}</p>
39|            </article>
40|          `;
41|        })
42|        .join("");
43|    }
44|
45|    async function loadComments() {
46|      const listEl = document.getElementById("comments-list");
47|      if (!listEl) return;
48|      listEl.innerHTML = '<div class="text-75">加载中...</div>';
49|
50|      try {
51|        const resp = await fetch("/api/comments/all/", {
52|          method: "GET",
53|          headers: { Accept: "application/json" },
54|        });
55|
56|        const data = await resp.json();
57|        if (!resp.ok || !data?.ok) {
58|          throw new Error(data?.error || "加载失败");
59|        }
60|
61|        renderComments(data.list || []);
62|      } catch (e) {
63|        listEl.innerHTML = '<div class="text-75">加载失败，请检查后端是否启动</div>';
64|      }
65|    }
66|
67|    loadComments();
68|    document.addEventListener("astro:page-load", loadComments);
69|  </script>
70|</MainGridLayout>", "total_lines": 70, "file_size": 2355, "truncated": false, "is_binary": false, "is_image": false}

