{"content": "1|// 本地教学演示：只校验下列固定 Schema，不是通用 JSON Schema 引擎。
2|export const schema = {
3|	type: "object",
4|	properties: {
5|		topic: { type: "string" },
6|		minutes: { type: "integer" },
7|		verified: { type: "boolean" },
8|	},
9|	required: ["topic", "minutes", "verified"],
10|	additionalProperties: false,
11|} as const;
12|
13|export type ValidationResult = {
14|	parseOk: boolean;
15|	schemaOk: boolean | null;
16|	errors: string[];
17|	parseMessage: string;
18|};
19|
20|export type TeachingSample = {
21|	id: string;
22|	label: string;
23|	json: string;
24|	expectedParse: boolean;
25|	expectedSchema: boolean | null;
26|};
27|
28|// 人工编写的本地教学样例，不是模型生成结果或 API 实测。
29|export const samples: TeachingSample[] = [
30|	{
31|		id: "valid",
32|		label: "本地教学 · 合法对象",
33|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20,\n  "verified": false\n}',
34|		expectedParse: true,
35|		expectedSchema: true,
36|	},
37|	{
38|		id: "syntax",
39|		label: "本地教学 · JSON 语法错误",
40|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20,\n  "verified": false,\n}',
41|		expectedParse: false,
42|		expectedSchema: null,
43|	},
44|	{
45|		id: "missing",
46|		label: "本地教学 · 缺少必填字段",
47|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20\n}',
48|		expectedParse: true,
49|		expectedSchema: false,
50|	},
51|	{
52|		id: "type",
53|		label: "本地教学 · 字段类型错误",
54|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": "20",\n  "verified": false\n}',
55|		expectedParse: true,
56|		expectedSchema: false,
57|	},
58|	{
59|		id: "extra",
60|		label: "本地教学 · 额外字段",
61|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20,\n  "verified": false,\n  "note": "不允许的字段"\n}',
62|		expectedParse: true,
63|		expectedSchema: false,
64|	},
65|	{
66|		id: "untrue",
67|		label: "本地教学 · 结构合规但观点错误",
68|		json: '{\n  "topic": "Schema 合规意味着事实一定正确",\n  "minutes": 20,\n  "verified": true\n}',
69|		expectedParse: true,
70|		expectedSchema: true,
71|	},
72|];
73|
74|export function validateJSON(text: string): ValidationResult {
75|	let value: unknown;
76|	try {
77|		value = JSON.parse(text);
78|	} catch (error) {
79|		return {
80|			parseOk: false,
81|			schemaOk: null,
82|			errors: [],
83|			parseMessage: `JSON 语法解析失败：${error instanceof Error ? error.message : "无效 JSON"}`,
84|		};
85|	}
86|	const errors: string[] = [];
87|	if (value === null || typeof value !== "object" || Array.isArray(value)) {
88|		errors.push("根值必须是对象，不能是 null、数组或基本类型。");
89|	} else {
90|		const object = value as Record<string, unknown>;
91|		for (const key of Object.keys(object)) {
92|			if (!Object.prototype.hasOwnProperty.call(schema.properties, key)) {
93|				errors.push(`不允许额外字段：${key}。`);
94|			}
95|		}
96|		for (const key of schema.required) {
97|			if (!Object.prototype.hasOwnProperty.call(value, key)) {
98|				errors.push(`缺少必填字段：${key}。`);
99|				continue;
100|			}
101|			const field = object[key];
102|			const type = schema.properties[key].type;
103|			const valid = type === "integer"
104|				? typeof field === "number" && Number.isFinite(field) && Number.isInteger(field)
105|				: typeof field === type;
106|			if (!valid) {
107|				errors.push(`字段 ${key} 必须是 ${type}${type === "integer" ? "（有限整数）" : ""}。`);
108|			}
109|		}
110|	}
111|	return {
112|		parseOk: true,
113|		schemaOk: errors.length === 0,
114|		errors,
115|		parseMessage: "JSON 语法解析成功。",
116|	};
117|}", "total_lines": 117, "file_size": 3382, "truncated": false, "is_binary": false, "is_image": false}

{"content": "1|import assert from "node:assert/strict";
2|import test from "node:test";
3|
4|import * as validator from "../src/components/homework/validator.ts";
5|
6|test("exports the exact fixed teaching schema", () => {
7|	assert.deepEqual(validator.schema, {
8|		type: "object",
9|		properties: {
10|			topic: { type: "string" },
11|			minutes: { type: "integer" },
12|			verified: { type: "boolean" },
13|		},
14|		required: ["topic", "minutes", "verified"],
15|		additionalProperties: false,
16|	});
17|});
18|
19|test("accepts a valid object including zero and false", () => {
20|	assert.equal(typeof validator.validateJSON, "function");
21|	const result = validator.validateJSON('{"topic":"","minutes":0,"verified":false}');
22|	assert.equal(result.parseOk, true);
23|	assert.equal(result.schemaOk, true);
24|	assert.deepEqual(result.errors, []);
25|	assert.equal(typeof result.parseMessage, "string");
26|	assert.ok(result.parseMessage.length > 0);
27|});
28|
29|test("requires every field as an own property", () => {
30|	for (const field of ["topic", "minutes", "verified"]) {
31|		const value = { topic: "x", minutes: 1, verified: true };
32|		delete value[field];
33|		assertSchemaFailure(JSON.stringify(value), field);
34|	}
35|	assert.equal(validator.validateJSON("{}").errors.length, 3);
36|	Object.defineProperty(Object.prototype, "topic", { value: "inherited", configurable: true });
37|	try {
38|		assertSchemaFailure('{"minutes":1,"verified":true}', "topic");
39|	} finally {
40|		delete Object.prototype.topic;
41|	}
42|});
43|
44|test("enforces field types without coercion, rejecting fractions and infinity", () => {
45|	const wrongValues = {
46|		topic: [null, 1, true, [], {}],
47|		minutes: [null, "0", false, [], {}, 1.5],
48|		verified: [null, "false", 0, [], {}],
49|	};
50|	for (const [field, values] of Object.entries(wrongValues)) {
51|		for (const value of values) {
52|			assertSchemaFailure(JSON.stringify({ topic: "x", minutes: 1, verified: true, [field]: value }), field);
53|		}
54|	}
55|	for (const number of ["1e400", "-1e400"]) {
56|		assertSchemaFailure(`{"topic":"x","minutes":${number},"verified":true}`, "minutes");
57|	}
58|	for (const number of ["-1", "1.0", "1e2"]) {
59|		assert.equal(validator.validateJSON(`{"topic":"x","minutes":${number},"verified":true}`).schemaOk, true);
60|	}
61|});
62|
63|test("rejects extra own keys including prototype-related names", () => {
64|	for (const key of ["extra", "__proto__", "constructor", "toString", "hasOwnProperty"]) {
65|		assertSchemaFailure(`{"topic":"x","minutes":1,"verified":true,"${key}":{}}`, key);
66|	}
67|	const result = validator.validateJSON('{"topic":1,"minutes":"2","extra":true}');
68|	assert.equal(result.errors.length, 4);
69|});
70|
71|test("exports six local teaching samples with verified expectations", () => {
72|	assert.ok(Array.isArray(validator.samples));
73|	assert.deepEqual(validator.samples.map((sample) => sample.id), ["valid", "syntax", "missing", "type", "extra", "untrue"]);
74|	const expected = [[true, true], [false, null], [true, false], [true, false], [true, false], [true, true]];
75|	for (const [index, sample] of validator.samples.entries()) {
76|		assert.equal(typeof sample.json, "string");
77|		assert.match(sample.label, /本地教学/);
78|		assert.deepEqual([sample.expectedParse, sample.expectedSchema], expected[index]);
79|		const result = validator.validateJSON(sample.json);
80|		assert.deepEqual([result.parseOk, result.schemaOk], expected[index], sample.id);
81|	}
82|	assert.equal(JSON.parse(validator.samples[5].json).topic, "Schema 合规意味着事实一定正确");
83|});
84|
85|function assertSchemaFailure(text, field) {
86|	const result = validator.validateJSON(text);
87|	assert.equal(result.parseOk, true, text);
88|	assert.equal(result.schemaOk, false, text);
89|	assert.ok(result.errors.length > 0, text);
90|	assert.ok(result.errors.every((error) => typeof error === "string"));
91|	if (field) assert.ok(result.errors.some((error) => error.includes(field)), field);
92|}
93|
94|test("rejects non-object roots including null and arrays", () => {
95|	for (const text of ["null", "[]", '["x",0,false]', '"text"', "0", "true", "false"]) {
96|		assertSchemaFailure(text);
97|	}
98|});
99|
100|test("syntax failures do not attempt schema validation or execute code", () => {
101|	for (const text of ["", '{"topic":}', '{"topic":"x",}', '(()=>{throw new Error("executed")})()', "NaN", "Infinity"]) {
102|		const result = validator.validateJSON(text);
103|		assert.equal(result.parseOk, false, text);
104|		assert.equal(result.schemaOk, null, text);
105|		assert.deepEqual(result.errors, []);
106|		assert.match(result.parseMessage, /JSON/);
107|	}
108|});", "total_lines": 108, "file_size": 4376, "truncated": false, "is_binary": false, "is_image": false}

