2|export const schema = {
3|	type: "object",
4|	properties: {
5|		topic: { type: "string" },
6|		minutes: { type: "integer" },
7|		verified: { type: "boolean" },
8|	},
9|	required: ["topic", "minutes", "verified"],
10|	additionalProperties: false,
11|} as const;
12|
13|export type ValidationResult = {
14|	parseOk: boolean;
15|	schemaOk: boolean | null;
16|	errors: string[];
17|	parseMessage: string;
18|};
19|
20|export type TeachingSample = {
21|	id: string;
22|	label: string;
23|	json: string;
24|	expectedParse: boolean;
25|	expectedSchema: boolean | null;
26|};
27|
28|// 人工编写的本地教学样例，不是模型生成结果或 API 实测。
29|export const samples: TeachingSample[] = [
30|	{
31|		id: "valid",
32|		label: "本地教学 · 合法对象",
33|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20,\n  "verified": false\n}',
34|		expectedParse: true,
35|		expectedSchema: true,
36|	},
37|	{
38|		id: "syntax",
39|		label: "本地教学 · JSON 语法错误",
40|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20,\n  "verified": false,\n}',
41|		expectedParse: false,
42|		expectedSchema: null,
43|	},
44|	{
45|		id: "missing",
46|		label: "本地教学 · 缺少必填字段",
47|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20\n}',
48|		expectedParse: true,
49|		expectedSchema: false,
50|	},
51|	{
52|		id: "type",
53|		label: "本地教学 · 字段类型错误",
54|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": "20",\n  "verified": false\n}',
55|		expectedParse: true,
56|		expectedSchema: false,
57|	},
58|	{
