60|		label: "本地教学 · 额外字段",
61|		json: '{\n  "topic": "Structured Outputs",\n  "minutes": 20,\n  "verified": false,\n  "note": "不允许的字段"\n}',
62|		expectedParse: true,
63|		expectedSchema: false,
64|	},
65|	{
66|		id: "untrue",
67|		label: "本地教学 · 结构合规但观点错误",
68|		json: '{\n  "topic": "Schema 合规意味着事实一定正确",\n  "minutes": 20,\n  "verified": true\n}',
69|		expectedParse: true,
